import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.RQXGjTIX.js";const o="/appliedcraftedenergistics/upgrade-cards.png",u=JSON.parse('{"title":"元件升级卡","description":"","frontmatter":{},"headers":[],"relativePath":"guide/upgrades.md","filePath":"guide/upgrades.md"}'),n={name:"guide/upgrades.md"};function s(l,t,i,h,c,p){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="元件升级卡" tabindex="-1">元件升级卡 <a class="header-anchor" href="#元件升级卡" aria-label="Permalink to &quot;元件升级卡&quot;">​</a></h1><p><img src="'+o+'" alt="气体元件与升级卡"></p><h2 id="气体存储元件的卡" tabindex="-1">气体存储元件的卡 <a class="header-anchor" href="#气体存储元件的卡" aria-label="Permalink to &quot;气体存储元件的卡&quot;">​</a></h2><p>气体存储元件有 <strong>5 个升级槽</strong>，全部在<strong>元件工作台</strong>里安装。其中三张是 AE2 原生卡，四张是气体专属卡。</p><h3 id="ae2-原生卡" tabindex="-1">AE2 原生卡 <a class="header-anchor" href="#ae2-原生卡" aria-label="Permalink to &quot;AE2 原生卡&quot;">​</a></h3><table tabindex="0"><thead><tr><th>卡</th><th>对气体元件的效果</th></tr></thead><tbody><tr><td>反相卡</td><td>分区列表在“白名单 / 黑名单”之间切换</td></tr><tr><td>均分卡</td><td>把元件容量平均分给已存的气体种类</td></tr><tr><td>溢出销毁卡</td><td>元件满后销毁多余气体，避免堵塞网络</td></tr></tbody></table><p><strong>模糊卡不支持</strong>：气体 key 没有 fuzzy 值，AE2 自己的流体元件也没有注册它。</p><h3 id="气体专属卡" tabindex="-1">气体专属卡 <a class="header-anchor" href="#气体专属卡" aria-label="Permalink to &quot;气体专属卡&quot;">​</a></h3><p>气体元件按“虚拟压力容器”建模：<code>容量(GU) = 容积(L) × 额定气压(Pa) / 100,000</code>， 基础额定气压为 16 atm（CCB 安全线）。四张卡各自修改其中一个量：</p><table tabindex="0"><thead><tr><th>卡</th><th>上限</th><th>效果</th><th>1k 元件示例</th></tr></thead><tbody><tr><td><strong>高压卡</strong></td><td>1 张</td><td>额定气压 16 → <strong>24 atm</strong>（CCB 硬上限），容量 ×1.5</td><td>1,024,000 → 1,536,000 GU</td></tr><tr><td><strong>扩容卡</strong></td><td>4 张</td><td>每张虚拟容积 +50%（4 张 ×3），与高压卡相乘</td><td>4 张 → 3,072,000 GU</td></tr><tr><td><strong>多类型卡</strong></td><td>2 张</td><td>每张 +4 种气体（基础 5 → 9 → 13），上限受 AE2 的 63 种限制</td><td>12 种气体不再需要 3 张元件</td></tr><tr><td><strong>泄压阀卡</strong></td><td>1 张</td><td>拆卡 / 改配置导致容量小于存量时，自动排掉超出的气体</td><td>避免“已用字节 &gt; 总字节”的卡死状态</td></tr></tbody></table><blockquote><p><code>relief_valve_card</code> 的中文名是 <strong>泄压阀卡</strong>，与接口的 <strong>安全卡</strong> 是两张不同的卡。</p></blockquote><p>容量倍率公式：<code>(1 + 0.5 × 扩容卡数) × 1.5^(高压卡数)</code>。</p><h3 id="装卡后为什么字节数变了" tabindex="-1">装卡后为什么字节数变了 <a class="header-anchor" href="#装卡后为什么字节数变了" aria-label="Permalink to &quot;装卡后为什么字节数变了&quot;">​</a></h3><p>容量最终以 AE 字节表达，所以一张高压卡会让 1k 元件从 1,024 字节变成 1,536 字节。 tooltip 会同时给出：</p><ul><li>容量（GU）</li><li>等效体积</li><li>额定气压（atm）</li><li>虚拟容积（升）</li><li>可存气体种类数</li></ul><p><code>1 byte = 1,000 GU</code> 的全局契约不变；升级卡只提高<strong>该元件</strong>的字节上限。</p><h2 id="me-气体接口的卡-0-2-x" tabindex="-1">ME 气体接口的卡（0.2.x） <a class="header-anchor" href="#me-气体接口的卡-0-2-x" aria-label="Permalink to &quot;ME 气体接口的卡（0.2.x）&quot;">​</a></h2><p>ME 气体接口有 <strong>6 个升级槽</strong>：</p><table tabindex="0"><thead><tr><th>卡</th><th>上限</th><th>作用</th></tr></thead><tbody><tr><td>速度卡（AE2 原生）</td><td>4 张</td><td>提高每 tick 的网络补货/回收速度</td></tr><tr><td>逐槽控制卡</td><td>1 张</td><td>解锁逐槽输入 / 输出 / 双向 / 关闭模式</td></tr><tr><td>安全卡</td><td>1 张</td><td>压力达到 20 atm 时经 CCB 真实释放排气</td></tr></tbody></table><p>逐槽控制卡与安全卡只对 ME 气体接口有效。</p><h2 id="总线气体压力卡" tabindex="-1">总线气体压力卡 <a class="header-anchor" href="#总线气体压力卡" aria-label="Permalink to &quot;总线气体压力卡&quot;">​</a></h2><p><strong>气体压力卡</strong>（<code>gas_pressure_card</code>）是 AE2 <strong>输入 / 输出总线</strong>的升级卡：</p><ul><li>输出停止在目标压力；</li><li>输入只在高于目标压力时抽取；</li><li>右键循环预设，潜行右键回退。</li></ul><p>它不作用于气体存储元件，也不作用于 ME 气体接口。</p><h2 id="拆卡时的建议" tabindex="-1">拆卡时的建议 <a class="header-anchor" href="#拆卡时的建议" aria-label="Permalink to &quot;拆卡时的建议&quot;">​</a></h2><p>大容量元件装了扩容卡、又存了很多气时，直接拆卡会让元件“装不下”。 先装<strong>泄压阀卡</strong>，或先把气体挪走，再拆卡。</p>',26)])])}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
